def transform(grid):
    out = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    horizontal = [r for r in range(rows) if len(set(grid[r])) == 1]
    vertical = [c for c in range(cols) if len({grid[r][c] for r in range(rows)}) == 1]
    for r in horizontal:
        out[r] = [2] * cols
    for c in vertical:
        for r in range(rows):
            out[r][c] = 2
    return out
